async function mkRoom(){const nm=saveName();if(!nm){alert('اكتب اسمك أولاً');return}const rn=(document.getElementById('rnm').value.trim()||'مجموعة');try{await fb();const AB='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';let c='';for(let i=0;i<6;i++)c+=AB[Math.floor(Math.random()*AB.length)];await F.setDoc(F.doc(FDB,'rooms',c),{name:rn,createdAt:F.serverTimestamp(),lastMsgAt:F.serverTimestamp(),cb:uid()});await F.setDoc(F.doc(FDB,'rooms',c,'members',uid()),{n:chatName(),t:F.serverTimestamp()});const rs=myRooms();rs.unshift({c:c,n:rn});saveRooms(rs);location.hash='room/'+c}catch(e){alert('تعذر الإنشاء؛ تحقق من الاتصال')}}
