 if(c){try{const d=await F.getDoc(F.doc(FDB,'invites',c));if(!d.exists()||d.data().uid!==uid()||d.data().used===true)need=true;else{const t=d.data().t;if(!t||(Date.now()-t.toMillis())>864e5)need=true}}catch(e){}}
