 const lr=+ls('rlr_'+r.c,0);let un=0;try{const cq=await F.getCountFromServer(F.query(F.collection(FDB,'rooms',r.c,'messages'),F.where('ts','>',new Date(lr))));un=cq.data().count}catch(e){}
