async function compressImage(f){const bmp=await createImageBitmap(f);let w=bmp.width,h=bmp.height;const mx=1280;if(w>mx||h>mx){const sc=mx/Math.max(w,h);w=Math.round(w*sc);h=Math.round(h*sc)}const cv=document.createElement('canvas');cv.width=w;cv.height=h;cv.getContext('2d').drawImage(bmp,0,0,w,h);let q=0.75,url=cv.toDataURL('image/jpeg',q);while(url.length>620000&&q>0.3){q-=0.15;url=cv.toDataURL('image/jpeg',q)}if(url.length>900000)throw 0;return url}
function imgPick(code){const inp=document.createElement('input');inp.type='file';inp.accept='image/*';inp.onchange=async()=>{const f=inp.files&&inp.files[0];if(!f)return;try{const url=await compressImage(f);const cap=prompt('تعليق على الصورة (اختياري):');await sendMedia(code,'i',url,null,(cap||'').trim().slice(0,200))}catch(e){alert('تعذر إرسال الصورة')}};inp.click()}
async function sendMedia(code,k,x,dur,cap){try{const b=F.writeBatch(FDB);const msg={n:code.indexOf('dm:')===0?myName():chatName(),d:uid(),k:k,x:x,ts:F.serverTimestamp(),r:0};if(dur)msg.dur=dur;if(cap)msg.c=cap;if(code.indexOf('dm:')===0){const pid=code.slice(3);b.set(F.doc(F.collection(FDB,'dms',pid,'messages')),msg);b.set(F.doc(FDB,'dms',pid),{lastMsgAt:F.serverTimestamp(),lastMsgBy:uid()},{merge:true})}else{b.set(F.doc(F.collection(FDB,'rooms',code,'messages')),msg);b.set(F.doc(FDB,'rooms',code),{lastMsgAt:F.serverTimestamp()},{merge:true})}b.set(F.doc(FDB,'stats','global'),{msgsTotal:F.increment(1),msgsToday:F.increment(1)},{merge:true});await b.commit()}catch(e){alert('تعذر الإرسال')}}
function voiceRec(code){const box=document.getElementById('zkbox');if(!box)return;if(!navigator.mediaDevices||!window.MediaRecorder){alert('التسجيل الصوتي غير مدعوم في هذا المتصفح');return}
 navigator.mediaDevices.getUserMedia({audio:true}).then(stream=>{
 const mt=['audio/webm;codecs=opus','audio/webm','audio/mp4'].find(t=>MediaRecorder.isTypeSupported(t))||'';
 const rec=new MediaRecorder(stream,mt?{mimeType:mt}:{});const chunks=[];let sec=0;
 box.innerHTML='<div class="z" style="margin-top:8px;display:flex;align-items:center;gap:10px"><span style="color:#d43b3b;font-size:20px">●</span><b id="recTime">0:00</b><span style="flex:1;font-size:13px">جاري التسجيل… (حتى 90 ثانية)</span><button class="chip on" id="recSend">إرسال</button><button class="chip" id="recCancel">إلغاء</button></div>';box.scrollIntoView({behavior:'smooth'});
 const tm=setInterval(()=>{sec++;const el=document.getElementById('recTime');if(el)el.textContent=fmtDur(sec);if(sec>=90){const b2=document.getElementById('recSend');if(b2)b.click()}},1000);
 rec.ondataavailable=e=>{if(e.data&&e.data.size)chunks.push(e.data)};
 const halt=()=>{clearInterval(tm);stream.getTracks().forEach(t=>{try{t.stop()}catch(e){}})};
 document.getElementById('recCancel').onclick=()=>{rec.onstop=null;try{rec.stop()}catch(e){}halt();box.innerHTML=''};
 document.getElementById('recSend').onclick=()=>{rec.onstop=()=>{halt();const blob=new Blob(chunks,{type:rec.mimeType||'audio/webm'});box.innerHTML='';if(blob.size>660000){alert('التسجيل طويل جداً');return}const rd=new FileReader();rd.onload=async()=>{await sendMedia(code,'v',rd.result,sec)};rd.readAsDataURL(blob)};try{rec.stop()}catch(e){halt();box.innerHTML=''}};
 rec.start(250)}).catch(()=>alert('اسمح بالوصول للمايكروفون لتسجيل الصوت'))}
let _typT=0;
function noteTyping(code){if(window._hidden)return;const now=Date.now();if(now-_typT<3000)return;_typT=now;try{const path=code.indexOf('dm:')===0?['dms',code.slice(3),'typing',uid()]:['rooms',code,'typing',uid()];F.setDoc(F.doc(FDB,path[0],path[1],path[2],path[3]),{n:chatName(),ts:F.serverTimestamp()}).catch(()=>{});if(window._typClear)clearTimeout(window._typClear);window._typClear=setTimeout(()=>{F.deleteDoc(F.doc(FDB,path[0],path[1],path[2],path[3])).catch(()=>{})},5000)}catch(e){}}
function clearTyping(code){try{const path=code.indexOf('dm:')===0?['dms',code.slice(3),'typing',uid()]:['rooms',code,'typing',uid()];F.deleteDoc(F.doc(FDB,path[0],path[1],path[2],path[3])).catch(()=>{})}catch(e){}}
function watchTyping(path){const coll=path.indexOf('dm:')===0?F.collection(FDB,'dms',path.slice(3),'typing'):F.collection(FDB,'rooms',path,'typing');return F.onSnapshot(coll,s=>{const now=Date.now();const names=[];s.forEach(d=>{if(d.id===uid())return;const v=d.data();if(v.ts&&now-v.ts.toMillis()<8000)names.push(v.n)});const el=document.getElementById('typingBar');if(el)el.textContent=names.length?'✍ يكتب الآن: '+names.join('، '):''})}
function updateTicks(){try{const mp=window._msgPath||'';document.querySelectorAll('#msgs [data-mine="1"]').forEach(el=>{const ts=+el.dataset.mts||0;if(!ts)return;const rd=window._reads||{};let read=false;
 if(mp.indexOf('rooms/')===0){const others=Object.keys(rd).filter(u=>u!==uid());read=others.length>0&&others.every(u=>(rd[u]||0)>=ts)}
 else if(mp.indexOf('dms/')===0){read=Object.keys(rd).some(u=>u!==uid()&&(rd[u]||0)>=ts)}
 const tk=el.querySelector('.tk');if(tk){tk.textContent=read?'✓✓':'✓';tk.style.color=read?'#53bdeb':''}})}catch(e){}}
function markReadServer(){if(window._hidden)return;try{const mp=window._msgPath||'';const now=Date.now();if(window._lrW&&now-window._lrW<8000)return;window._lrW=now;
 if(mp.indexOf('rooms/')===0)F.setDoc(F.doc(FDB,'rooms',mp.split('/')[1],'members',uid()),{lr:F.serverTimestamp()},{merge:true}).catch(()=>{});
 else if(mp.indexOf('dms/')===0)F.setDoc(F.doc(FDB,'dms',mp.split('/')[1],'reads',uid()),{lr:F.serverTimestamp()}).catch(()=>{})}catch(e){}}
function bindSwipe(){const m=document.getElementById('msgs');if(!m||m._swBound)return;m._swBound=true;let sx=0,sy=0,mid=null;
 m.addEventListener('touchstart',e=>{const t=e.touches[0];sx=t.clientX;sy=t.clientY;const b=e.target.closest('[data-mid]');mid=b?b.dataset.mid:null},{passive:true});
 m.addEventListener('touchend',e=>{if(!mid)return;const t=e.changedTouches[0];const dx=t.clientX-sx,dy=t.clientY-sy;if(Math.abs(dx)>70&&Math.abs(dy)<45)replyTo(mid);mid=null},{passive:true})}
