function vpToggle(id){const m=(roomMsgs||[]).find(x=>x.id===id);if(!m)return;const btn=document.getElementById('vpb_'+id);
 if(window._vp&&window._vp.id===id&&window._vp.a&&!window._vp.a.paused){window._vp.a.pause();if(btn)btn.innerHTML=SVG_PLAY;return}
 if(window._vp&&window._vp.a){window._vp.a.pause();const ob=document.getElementById('vpb_'+window._vp.id);if(ob)ob.innerHTML=SVG_PLAY}
 const a=new Audio(m.x);window._vp={id:id,a:a};
 a.ontimeupdate=()=>{const p=document.getElementById('vpp_'+id),t=document.getElementById('vpt_'+id);if(p&&a.duration)p.style.width=Math.min(100,a.currentTime/a.duration*100)+'%';if(t)t.textContent=fmtDur(Math.floor(a.currentTime))};
 a.onended=()=>{const p=document.getElementById('vpp_'+id),t=document.getElementById('vpt_'+id);if(p)p.style.width='0%';if(t)t.textContent=fmtDur(m.dur||Math.floor(a.duration||0));if(btn)btn.innerHTML=SVG_PLAY};
 if(btn)btn.innerHTML=SVG_PAUSE;a.play().catch(()=>{if(btn)btn.innerHTML=SVG_PLAY})}
function vpSeek(ev,id){if(!window._vp||window._vp.id!==id||!window._vp.a)return;const r=ev.currentTarget.getBoundingClientRect();const r2=(ev.clientX-r.left)/r.width;if(window._vp.a.duration)window._vp.a.currentTime=r2*window._vp.a.duration}
function voiceHtml(m){return '<div style="display:flex;align-items:center;gap:8px;min-width:190px;max-width:58vw"><button class="lb" id="vpb_'+m.id+'" onclick="vpToggle(\''+m.id+'\')" style="width:34px;height:34px;border-radius:50%;background:var(--gold);border:none;display:grid;place-items:center;flex:none;padding:0">'+SVG_PLAY+'</button><div style="flex:1;padding:8px 0;cursor:pointer" onclick="vpSeek(event,\''+m.id+'\')"><div style="height:4px;background:#ffffff33;border-radius:2px"><div id="vpp_'+m.id+'" style="height:4px;background:var(--gold);border-radius:2px;width:0%"></div></div></div><small id="vpt_'+m.id+'" style="font-size:11px;opacity:.7;flex:none">'+fmtDur(m.dur||0)+'</small></div>'}
