async function shareAyah(code,i){const s=Q[i];const a1=+document.getElementById('ay1').value;const a2=+document.getElementById('ay2').value||a1;if(!a1||a1<1||a1>s.ay.length||a2<a1||a2>s.ay.length){alert('رقم الآية غير صحيح');return}if(a2-a1>10){alert('اختر حتى ١٠ آيات في المرة');return}document.getElementById('zkbox').innerHTML='';await sendWirdText(code,(i+1)+'|'+a1+'|'+a2,'a')}
