 const btns=[[SVG_IMG+' صورة',"imgPick('"+code+"')"],[SVG_MIC+' تسجيل صوت',"voiceRec('"+code+"')"],['▤ ورد / سور / ختمة',"wirdPick('"+code+"')"],[SVG_DHKR+' شارك ذكر',"athkarPick('"+code+"')"]];
 if(canInv)btns.push([SVG_INV+' دعوة مستخدم',"location.hash='invite/"+code+"'"]);
