 d.innerHTML='<div class="chips" style="justify-content:center;flex-wrap:wrap">'+btns.map(b=>'<button class="chip" onclick="document.getElementById(\'delpick\').remove();'+b[1]+'">'+b[0]+'</button>').join('')+'</div>';
