async function memberTap(code,mid){if(mid===uid())return;try{await fb();const rd=await F.getDoc(F.doc(FDB,'rooms',code));if(!rd.exists())return;const cb=rd.data().cb;if(mid===cb)return;
 const me=await F.getDoc(F.doc(FDB,'rooms',code,'members',uid()));const iC=uid()===cb;const iA=me.exists()&&me.data().a===true;const iO=isOwner();
 if(!iC&&!iA&&!iO)return;
 const tm=await F.getDoc(F.doc(FDB,'rooms',code,'members',mid));const tA=tm.exists()&&tm.data().a===true;
 const btns=[];
 if(iC||iO)btns.push([tA?'إزالة الإشراف':'جعله مشرفاً',"setAdmin('"+code+"','"+mid+"',"+(!tA)+")"]);
 if(iC||iO||!tA)btns.push(['إزالة من المجموعة',"removeMember('"+code+"','"+mid+"')"]);
 if(btns.length)_sheet((tm.exists()&&tm.data().n)||'عضو',btns)}catch(e){}}
