function ownerDevicesPage(f){window._ownFilter=(f==null?(window._ownFilter==null?0:window._ownFilter):f);if(location.hash!=='#owner/devices'){location.hash='owner/devices';return}setT('الأجهزة',1);app.innerHTML='<div class="z"><h3>الأجهزة</h3><div class="chips">'+[['كل الأجهزة',0],['فتحت اليوم',1],['مفتوحة الآن',2]].map(x=>'<button class="chip'+(window._ownFilter===x[1]?' on':'')+'" onclick="ownerDevicesPage('+x[1]+')">'+x[0]+'</button>').join('')+'</div></div><div class="z" id="devBox"><p>جاري التحميل...</p></div>';ownerList(window._ownFilter)}
function ownerList(f,sc){window._ownFilter=f;const t0=new Date();t0.setHours(0,0,0,0);const arr=(window._ownDevs||[]).filter(v=>f===2?v._on:(f?(v.last&&v.last.toMillis()>=t0.getTime()):true));const fmt=t=>t?new Date(t.toMillis()).toLocaleString('ar',{day:'numeric',month:'numeric',hour:'2-digit',minute:'2-digit'}):'—';
 const rows=arr.map(v=>'<div class="sr"><div class="n" style="font-size:11px;background:'+(v._on?'#1e7e4f':'#4a5a6a')+'">●</div><div style="flex:1;min-width:0"><div class="nm" style="font-size:14px">'+('<b style="color:var(--gold)">'+esc(v.n||'زائر')+'</b> · ')+esc(v._id.slice(0,6))+' · '+(v.model?esc(v.model)+' · ':'')+esc(v.os||'')+' '+esc(v.br||'')+' · '+esc(v.cls||'')+(v.inst?' · مثبّت':' · متصفح')+'</div><div class="m">'+(v.lang?esc(v.lang)+' · ':'')+'IP '+(v.ip?esc(v.ip):'—')+' · أول ظهور '+fmt(v.first)+' · آخر ظهور '+fmt(v.last)+'</div></div></div>');
 const el=document.getElementById('devBox');if(el){el.innerHTML='<h3>'+(f===2?'الأجهزة المفتوحة الآن':(f?'أجهزة فتحت اليوم':'كل الأجهزة'))+' ('+rows.length+')</h3>'+(rows.join('')||'<p>لا أجهزة بعد.</p>');if(sc)el.scrollIntoView({behavior:'smooth',block:'start'})}}
async function ownerUsers(){const el=document.getElementById('ownUsers');if(el)el.innerHTML='جاري التحميل...';try{await fb();const sn=await F.getDocs(F.query(F.collection(FDB,'users'),F.where('dir','!=',false)));const arr=[];sn.forEach(d=>arr.push({id:d.id,...d.data()}));arr.sort((a,b)=>String(a.username||'').localeCompare(String(b.username||''),'ar'));if(el)el.innerHTML=arr.map(u=>'<div class="sr"><div class="nm" style="flex:1">'+esc(u.username||'بدون اسم')+(u.hideOn?' <small style="color:#f0a0a0">مخفي</small>':'')+'<br><small style="opacity:.6">'+esc(u.id)+'</small></div></div>').join('')||'لا حسابات مسجلة'}catch(e){if(el)el.innerHTML='تعذر التحميل'}}
async function ownerRooms(){const el=document.getElementById('ownRooms');if(el)el.innerHTML='جاري التحميل...';try{await fb();const rs=await F.getDocs(F.query(F.collection(FDB,'rooms'),F.orderBy('lastMsgAt','desc'),F.limit(200)));const rows=[];for(const d of rs.docs){const v=d.data();let mc=0;try{const cq=await F.getCountFromServer(F.query(F.collection(FDB,'rooms',d.id,'members')));mc=cq.data().count}catch(e){}rows.push('<div class="sr"><div class="nm" style="flex:1">'+esc(v.name||d.id)+'<br><small style="opacity:.6">'+d.id+' · '+mc+' عضو</small></div><div class="m"><button class="lb" onclick="monRoom(\''+d.id+'\')">مراقبة خفية</button> <button class="lb" style="color:#f0a0a0" onclick="deleteRoom(\''+d.id+'\')">حذف</button></div></div>')}if(el)el.innerHTML=rows.join('')||'لا غرف بعد'}catch(e){if(el)el.innerHTML='تعذر التحميل'}}
function monRoom(c){window._hidden=true;location.hash='room/'+c}
async function ownerBans(){const el=document.getElementById('ownBans');if(el)el.innerHTML='جاري التحميل...';try{await fb();const bs=await F.getDocs(F.collection(FDB,'bans'));const rows=[];bs.forEach(d=>{const v=d.data();rows.push('<div class="sr"><div class="nm" style="flex:1">'+esc(v.n||d.id)+'</div><div class="m"><button class="lb" onclick="unban(\''+d.id+'\')">إلغاء الحظر</button></div></div>')});if(el)el.innerHTML=rows.join('')||'لا محظورين'}catch(e){if(el)el.innerHTML='تعذر التحميل'}}
async function unban(u){try{await fb();await F.deleteDoc(F.doc(FDB,'bans',u));ownerBans()}catch(e){alert('تعذر إلغاء الحظر')}}
async function banUser(u,n){if(!confirm('حظر '+(n||'هذا العضو')+' من الإرسال في كل التطبيق؟'))return;try{await fb();await F.setDoc(F.doc(FDB,'bans',u),{n:(n||'').slice(0,40),t:F.serverTimestamp()});alert('تم الحظر')}catch(e){alert('تعذر الحظر')}}
async function annSet(){const t=(document.getElementById('annTxt').value||'').trim().slice(0,300);if(!t)return;try{await fb();await F.setDoc(F.doc(FDB,'settings','app'),{banner:t},{merge:true});ownerPage()}catch(e){alert('تعذر النشر')}}
async function annClear(){try{await fb();await F.setDoc(F.doc(FDB,'settings','app'),{banner:''},{merge:true});ownerPage()}catch(e){alert('تعذر')}}
async function forceUpd(on){try{await fb();await F.setDoc(F.doc(FDB,'settings','app'),{minVer:on?window.APP_VER:0},{merge:true});ownerPage()}catch(e){alert('تعذر')}}
async function ownerPass(){const a=document.getElementById('np1').value.trim(),b=document.getElementById('np2').value.trim();if(a.length<6){alert('٦ أحرف على الأقل');return}if(a!==b){alert('غير متطابقتين');return}try{await fb();await F.setDoc(F.doc(FDB,'settings','owner'),{h:await sha(a.normalize('NFKC'))});alert('تم تغيير كلمة السر')}catch(e){alert('تعذر التغيير')}}

async function getOwnerHash(){try{await fb();const d=await F.getDoc(F.doc(FDB,'settings','owner'));if(d.exists()&&d.data().h)return d.data().h}catch(e){}return OWNER_HASH}
async function ownerTry(){const v=document.getElementById('opass').value.trim().normalize('NFKC');if(v&&await sha(v)===await getOwnerHash()){window._ownerOK=true;ownerPage()}else alert('كلمة سر خاطئة')}
if(!window._lpInit){window._lpInit=true;let _lpt=null;document.addEventListener('touchstart',e=>{const b=e.target.closest&&e.target.closest('[data-mid]');if(!b)return;_lpt=setTimeout(()=>{msgMenu(null,b.getAttribute('data-mid'))},500)},{passive:true});document.addEventListener('touchend',()=>{clearTimeout(_lpt)},{passive:true});document.addEventListener('touchmove',()=>{clearTimeout(_lpt)},{passive:true});}
